import * as path from "node:path";
import { createGraph, loadModule } from "./subject.mjs";

const root = path.resolve(import.meta.dirname, "..");

const gate = await loadModule(root, "packages/agent/src/harness/execution/effect-gate.ts");
console.log("gate exports", Object.keys(gate));

const tools = await loadModule(root, "packages/agent/src/harness/execution/tools.ts", {
	validateToolArguments: () => ({}),
	withAbortSignal: (signal, context) => ({ ...context, abortSignal: signal }),
});
console.log("tools exports", Object.keys(tools));

import * as path from "node:path";
import { createGraph } from "./subject.mjs";

const root = path.resolve(import.meta.dirname, "..");

const modules = [
	"packages/agent/src/harness/runtime/drive/tools.ts",
	"packages/agent/src/harness/runtime/drive/tool-placement.ts",
	"packages/agent/src/harness/runtime/progress.ts",
	"packages/agent/src/harness/execution/tools.ts",
	"packages/agent/src/harness/execution/effect-gate.ts",
	"packages/agent/src/harness/hooks.ts",
	"packages/agent/src/harness/session/values.ts",
	"packages/agent/src/harness/session/commit.ts",
	"packages/agent/src/harness/session/types.ts",
];

class SessionInvariantError extends Error {
	constructor(message) {
		super(message);
		this.name = "SessionInvariantError";
	}
}

const bindings = {
	validateToolArguments: (_tool, call) => call.arguments,
	withAbortSignal: (signal, context) => ({ ...context, abortSignal: signal }),
	startHarnessSpan: (_name, _attributes, callback, context) =>
		callback({ setAttributes() {}, setStatus() {} }, context),
	SessionInvariantError,
};

const graph = createGraph(root, modules, bindings);
for (const name of modules) {
	try {
		const namespace = await graph.module(name);
		console.log("ok", name, Object.keys(namespace).slice(0, 8));
	} catch (error) {
		console.log("FAIL", name, error?.message);
	}
}

/**
 * Cross-module regression coverage for `advanced/execution-lifecycle/correction`.
 *
 * Real production modules linked through `.prale-eval/subject.mjs`:
 *   - runtime/drive/tools.ts          (recovery + tool procedure)
 *   - runtime/drive/tool-placement.ts (durable placement of staged results)
 *   - runtime/progress.ts             (tool progress channel)
 *   - runtime/types.ts                (real Drive + its effect gate)
 *   - execution/tools.ts              (tool execution + after-tool finalization)
 *   - execution/effect-gate.ts        (effect admission gate)
 *   - hooks.ts                        (real HookRegistry after-tool aggregation)
 *   - session/values.ts, session/commit.ts, session/types.ts (addresses/writes)
 *
 * Boundary fakes: the pi-ai validator, chord context helpers, the telemetry span
 * factory, the session invariant error type, plus an in-memory Lane/Session that
 * stores the writes these modules emit. No task-specific adapters are used.
 */
import assert from "node:assert/strict";
import * as path from "node:path";
import { createGraph } from "./subject.mjs";

const ROOT = path.resolve(import.meta.dirname, "..");
const DRIVE_TOOLS = "packages/agent/src/harness/runtime/drive/tools.ts";
const TOOL_PLACEMENT = "packages/agent/src/harness/runtime/drive/tool-placement.ts";
const PROGRESS = "packages/agent/src/harness/runtime/progress.ts";
const DRIVE_TYPES = "packages/agent/src/harness/runtime/types.ts";
const EXECUTION_TOOLS = "packages/agent/src/harness/execution/tools.ts";
const EFFECT_GATE = "packages/agent/src/harness/execution/effect-gate.ts";
const HOOKS = "packages/agent/src/harness/hooks.ts";
const VALUES = "packages/agent/src/harness/session/values.ts";
const COMMIT = "packages/agent/src/harness/session/commit.ts";
const SESSION_TYPES = "packages/agent/src/harness/session/types.ts";

const MODULES = [
	DRIVE_TOOLS,
	TOOL_PLACEMENT,
	PROGRESS,
	DRIVE_TYPES,
	EXECUTION_TOOLS,
	EFFECT_GATE,
	HOOKS,
	VALUES,
	COMMIT,
	SESSION_TYPES,
];

class SessionInvariantError extends Error {
	constructor(message) {
		super(message);
		this.name = "SessionInvariantError";
	}
}

/** Structural snapshot that erases realm-specific prototypes before comparison. */
const plain = (value) => JSON.parse(JSON.stringify(value));

function deferred() {
	let resolve;
	let reject;
	const promise = new Promise((resolvePromise, rejectPromise) => {
		resolve = resolvePromise;
		reject = rejectPromise;
	});
	promise.catch(() => {});
	return { promise, resolve, reject };
}

function createGraphFixture() {
	return createGraph(ROOT, MODULES, {
		// pi-ai argument validation: the boundary validator is irrelevant to the lifecycle assertions.
		validateToolArguments: (_tool, call) => call.arguments,
		withAbortSignal: (signal, context) => ({ ...context, abortSignal: signal }),
		withoutAbortSignal: (context) => ({ ...context, abortSignal: undefined }),
		startHarnessSpan: (_name, _attributes, callback, context) =>
			callback({ setAttributes() {}, setStatus() {} }, context),
		SessionInvariantError,
	});
}

const graph = createGraphFixture();
const driveTools = await graph.module(DRIVE_TOOLS);
const execution = await graph.module(EXECUTION_TOOLS);
const effectGate = await graph.module(EFFECT_GATE);
const hooksModule = await graph.module(HOOKS);
const values = await graph.module(VALUES);
const commit = await graph.module(COMMIT);
const driveTypes = await graph.module(DRIVE_TYPES);

/** In-memory durable store plus a fake Lane that only honours the Lane surface drive/tools.ts uses. */
function createLaneFixture({ hooks, tools, toolContext = undefined, mode = "sequential", onBatch = undefined }) {
	const values_ = new Map();
	const entries = new Map();
	const log = [];
	let seq = 0;
	let timestamp = 0;
	let generated = 0;

	const keyOf = (namespace, key) => `${namespace}\u0000${key}`;
	const reader = {
		async getValue(address) {
			return values_.get(keyOf(address.namespace, address.key));
		},
		async scanValues(prefix) {
			return [...values_.values()].filter(
				(stored) =>
					stored.address.namespace === prefix.namespace && stored.address.key.startsWith(prefix.key),
			);
		},
		async getEntries(ids) {
			const found = new Map();
			for (const id of ids) {
				const entry = entries.get(id);
				if (entry !== undefined) found.set(id, entry);
			}
			return found;
		},
		async readList() {
			return [];
		},
	};

	const applyWrite = (write) => {
		seq += 1;
		if (write.kind === "entry") {
			entries.set(write.entry.id, { ...write.entry, seq });
			return;
		}
		if (write.kind !== "value") return;
		if (write.op === "set") {
			values_.set(keyOf(write.namespace, write.key), {
				address: { namespace: write.namespace, key: write.key, kind: "value" },
				value: write.value,
				seq,
			});
			return;
		}
		values_.delete(keyOf(write.namespace, write.key));
	};

	const applyCommit = (writes) => {
		const stagesOutcome = writes.some(
			(write) => write.kind === "value" && write.op === "set" && write.namespace === "pi.pending.entry",
		);
		const dropsCheckpoint = writes.some(
			(write) => write.kind === "value" && write.op === "delete" && write.namespace === "pi.pending.tool_output",
		);
		if (!stagesOutcome && dropsCheckpoint) log.push("replay_commit");
		const result = commit.prepareStorageCommit(writes, seq + 1, (timestamp += 1));
		for (const write of writes) applyWrite(write);
		return result;
	};

	const lane = {
		name: "main",
		state: undefined,
		hooks,
		session: { idGenerator: { next: () => `generated-${(generated += 1)}` } },
		values: values_,
		entries,
		log,
		readConfig: () => ({
			tools,
			resources: {},
			streamOptions: {},
			retryPolicy: { enabled: false, maxRetries: 0, baseDelayMs: 0 },
			compaction: { enabled: false, reserveTokens: 0, keepRecentTokens: 0 },
			steeringMode: "all",
			followUpMode: "all",
			toolExecution: mode,
			toolContext,
			systemPrompt: undefined,
			toProviderMessages: (messages) => messages,
			entryProjectors: {},
		}),
		async emitBatch(events) {
			log.push(...events.map((event) => event.type));
			await onBatch?.(events);
		},
		async command(plan) {
			const decision = await plan(lane.state, reader);
			if (decision.kind === "return") return decision.result;
			if (decision.kind === "reject") throw decision.error;
			const result = applyCommit(decision.writes);
			lane.state = decision.next;
			const materialized = decision.materialize(result);
			const events = decision.events?.(result) ?? [];
			if (events.length !== 0) await lane.emitBatch(events);
			return materialized;
		},
		async settleOperation(_capability, plan) {
			return lane.command(async (state) => {
				const operation = state.operation;
				const decision = await plan(state, operation.state, operation.meta, reader);
				if (decision.kind === "commit") {
					return {
						kind: "commit",
						writes: decision.writes,
						next: {
							...state,
							...(decision.lane ?? {}),
							operation: { meta: operation.meta, state: decision.operationState },
						},
						materialize: decision.materialize,
						...(decision.events === undefined ? {} : { events: decision.events }),
					};
				}
				if (decision.kind !== "finish") return decision;
				return {
					kind: "commit",
					writes: decision.writes,
					next: {
						...state,
						...(decision.lane ?? {}),
						lastOperationId: operation.meta.operationId,
						operation: null,
					},
					materialize: decision.materialize,
					...(decision.events === undefined ? {} : { events: decision.events }),
				};
			});
		},
		async continueOperation(capability, plan) {
			return lane.settleOperation(capability, async (state, latest, meta, valueReader) => {
				if (latest.control.status === "cancel_requested") return { kind: "return", result: { kind: "cancel_requested" } };
				const decision = await plan(state, latest, meta, valueReader);
				if (decision.kind === "return") return { kind: "return", result: { kind: "result", value: decision.result } };
				return { ...decision, materialize: (result) => ({ kind: "result", value: decision.materialize(result) }) };
			});
		},
	};
	return lane;
}

const ASSISTANT = "assistant-1";
const OPERATION = "operation-1";
const TURN = "turn-1";

function toolCall(index, name, arguments_) {
	return { type: "toolCall", id: `call-${index}`, name, arguments: arguments_ };
}

function harnessTool(name, execute, replay = "never") {
	return {
		name,
		label: name,
		description: name,
		parameters: { type: "object", properties: { value: { type: "string" } }, required: ["value"] },
		replay,
		execute: async (_toolCallId, args, onUpdate, _toolContext, invocation, context) =>
			execute({ args, onUpdate, invocation, context }),
	};
}

function operationFor(calls) {
	return {
		at: "tools",
		control: { status: "running" },
		settings: {
			compaction: { enabled: false, reserveTokens: 0, keepRecentTokens: 0 },
			steeringMode: "all",
			followUpMode: "all",
			toolExecution: "sequential",
		},
		batch: {
			assistantEntryId: ASSISTANT,
			configuration: {
				model: { provider: "faux", modelId: "faux" },
				thinkingLevel: "off",
				activeToolNames: calls.map((call) => call.name),
			},
			turnId: TURN,
			calls: calls.map((call, index) => ({
				status: "planned",
				sourceIndex: index,
				resultEntryId: `result-${index}`,
			})),
		},
		latestAssistantEntryId: ASSISTANT,
	};
}

function seed(lane, calls, callStates, operation, extraWrites = []) {
	lane.entries.set(ASSISTANT, {
		id: ASSISTANT,
		parentId: null,
		type: "message",
		message: { role: "assistant", content: calls, stopReason: "toolUse", timestamp: 20 },
		seq: 0,
	});
	const state = { ...operation, batch: { ...operation.batch, calls: callStates } };
	lane.state = {
		tipId: ASSISTANT,
		configuration: operation.batch.configuration,
		inbox: [],
		lastOperationId: null,
		operation: {
			meta: {
				operationId: OPERATION,
				lane: "main",
				sourceTipId: null,
				startedAt: 10,
				intent: { kind: "run", promptEntryIds: [] },
			},
			state,
		},
	};
	for (const write of extraWrites) {
		lane.state.operation.state = lane.state.operation.state;
		lane.command(async () => ({ kind: "commit", writes: [write], next: lane.state, materialize: () => undefined }));
	}
	return state;
}

function insertValue(lane, address, value) {
	const writes = [values.setValue(address, value)];
	// Apply directly through the same commit path the modules use, synchronously enough for seeding.
	lane.command(async () => ({ kind: "commit", writes, next: lane.state, materialize: () => undefined }));
}

const drive = new driveTypes.Drive({ operationId: OPERATION }, {});
const context = drive.context;

/* ---------------------------------------------------------------------------------------------------------- *
 * 1. Effect gate: a closed aborting gate makes the terminal error authoritative for later admissions.
 * ---------------------------------------------------------------------------------------------------------- */

{
	const { gate, control } = effectGate.createGate();
	const pendingCancellation = deferred();
	control.beginAbort(pendingCancellation.promise);

	let refusal;
	try {
		gate.admit(() => "admitted");
	} catch (error) {
		refusal = error;
	}
	assert.ok(refusal instanceof effectGate.AbortRequested, "an aborting gate refuses admission with AbortRequested");
	assert.equal(refusal.cancellation, pendingCancellation.promise);

	const terminal = new Error("terminal harness fault");
	control.close(terminal);
	assert.equal(gate.signal.aborted, true, "closing an aborting gate still signals admitted work");
	assert.equal(gate.signal.reason, terminal, "the terminal error becomes the signal reason");

	const admitted = () => {
		try {
			gate.admit(() => "admitted");
			return undefined;
		} catch (error) {
			return error;
		}
	};
	assert.equal(admitted(), terminal, "the terminal error is authoritative for future admissions");

	// A cancellation that lands after the closure must not resurrect the abort path.
	const laterCancellation = deferred();
	control.beginAbort(laterCancellation.promise);
	control.signalAbort();
	assert.equal(admitted(), terminal, "a pending cancellation does not override the closed gate");
	assert.equal(gate.signal.reason, terminal, "the closure reason survives a late cancellation");

	control.close(new Error("second fault"));
	assert.equal(admitted(), terminal, "the first closure remains authoritative");
}

/* ---------------------------------------------------------------------------------------------------------- *
 * 2. Real Drive gate: closing an aborting drive gate replaces the pending cancellation.
 * ---------------------------------------------------------------------------------------------------------- */

{
	const driveGate = new driveTypes.Drive({ operationId: "operation-gate" }, {});
	const cancellation = deferred();
	driveGate.beginAbort(cancellation.promise);
	let refusal;
	try {
		driveGate.gate.admit(() => undefined);
	} catch (error) {
		refusal = error;
	}
	assert.ok(refusal instanceof effectGate.AbortRequested);

	const terminal = new Error("drive fault");
	driveGate.closeGate(terminal);
	let afterClose;
	try {
		driveGate.gate.admit(() => undefined);
	} catch (error) {
		afterClose = error;
	}
	assert.equal(afterClose, terminal);
	assert.equal(driveGate.gate.signal.reason, terminal);
	const completion = await driveGate.completion.then(
		() => "settled",
		(error) => error,
	);
	assert.equal(completion, terminal, "the drive reports the terminal error");
}

/* ---------------------------------------------------------------------------------------------------------- *
 * 3. After-tool finalization: an explicit false/empty patch is applied, untouched fields and usage survive.
 * ---------------------------------------------------------------------------------------------------------- */

{
	const toolCall_ = toolCall(0, "echo", { value: "input" });
	const usage = {
		input: 1,
		output: 2,
		cacheRead: 0,
		cacheWrite: 0,
		totalTokens: 3,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
	};
	const cleared = { toolCall: toolCall_, tool: harnessTool("echo", () => {}), args: { value: "input" } };
	const executed = {
		result: { content: [{ type: "text", text: "original" }], details: { original: true }, usage, terminate: false },
		isError: true,
	};

	const kept = execution.finalizeToolCall(cleared, executed, { isError: false });
	assert.equal(kept.isError, false, "an after-tool patch can clear isError");
	assert.deepEqual(plain(kept.result.content), [{ type: "text", text: "original" }]);
	assert.deepEqual(plain(kept.result.details), { original: true });
	assert.deepEqual(plain(kept.result.usage), usage, "usage survives a patch that does not mention it");
	assert.equal(kept.terminate, false);

	const message = execution.createToolResultMessage(kept);
	assert.equal(message.isError, false);
	assert.deepEqual(plain(message.usage), usage);

	const patched = execution.finalizeToolCall(cleared, executed, {
		content: [],
		details: {},
		usage: undefined,
		isError: false,
	});
	assert.deepEqual(plain(patched.result.content), [], "an explicit empty content patch is applied");
	assert.deepEqual(plain(patched.result.details), {}, "an explicit empty details patch is applied");
	assert.deepEqual(plain(patched.result.usage), usage, "unspecified usage is preserved");
	assert.equal(patched.isError, false);

	const escalated = execution.finalizeToolCall(cleared, { result: { content: [], details: {} }, isError: false }, { isError: true });
	assert.equal(escalated.isError, true, "an explicit isError patch is applied in both directions");
}

/* ---------------------------------------------------------------------------------------------------------- *
 * 4. Recovery of a durable tool batch: non-cancelled safe/safe replay reruns, unsafe work is interrupted,
 *    and after-tool hook patches flow through to the durable transcript.
 * ---------------------------------------------------------------------------------------------------------- */

{
	const hooks = new hooksModule.HookRegistry(() => {});
	const calls = [toolCall(0, "safe", { value: "original" }), toolCall(1, "unsafe", { value: "original" })];
	const observations = [];
	const safeUsage = {
		input: 4,
		output: 5,
		cacheRead: 0,
		cacheWrite: 0,
		totalTokens: 9,
		cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
	};

	const safeExecute = async ({ args, onUpdate, invocation, context: toolCtx }) => {
		observations.push(["safe_execute", args.value, await invocation.getMemo("step/a")]);
		assert.ok(toolCtx.abortSignal === drive.gate.signal, "the tool sees the drive admission signal");
		onUpdate?.({ content: [{ type: "text", text: "partial" }], details: { partial: true } }, { checkpoint: true });
		return { content: [{ type: "text", text: "safe replay" }], details: { value: args.value }, usage: safeUsage };
	};
	const unsafeExecute = async () => {
		observations.push(["unsafe_execute"]);
		return { content: [{ type: "text", text: "must not run" }], details: {} };
	};

	const lane = createLaneFixture({
		hooks,
		tools: [harnessTool("safe", safeExecute, "safe"), harnessTool("unsafe", unsafeExecute, "never")],
		mode: "sequential",
	});
	const operation = operationFor(calls);
	seed(lane, calls, [], operation);
	const run = operationFor(calls);
	const seededRun = { ...run, control: { status: "running" } };
	lane.state.operation.state = seededRun;
	lane.state.operation.state.batch.calls = [
		{ status: "effect_pending", sourceIndex: 0, resultEntryId: "result-0", replay: "safe" },
		{ status: "effect_pending", sourceIndex: 1, resultEntryId: "result-1", replay: "never" },
	];

	insertValue(lane, values.operationToolArgs(OPERATION, TURN, 0), { value: "persisted" });
	insertValue(lane, values.operationToolArgs(OPERATION, TURN, 1), { value: "unsafe" });
	insertValue(lane, values.operationToolMemo(OPERATION, "result-0", "step/a"), { complete: true });
	insertValue(lane, values.pendingToolOutput(OPERATION, "result-0"), {
		content: [{ type: "text", text: "old progress" }],
		details: {},
	});
	insertValue(lane, values.pendingToolOutput(OPERATION, "result-1"), {
		content: [{ type: "text", text: "durable partial" }],
		details: { progress: "kept" },
	});

	const events = [];
	await lane.command(async () => ({ kind: "return", result: undefined }));
	const originalEmit = lane.emitBatch.bind(lane);
	lane.emitBatch = async (batch) => {
		events.push(...batch);
		await originalEmit(batch);
	};

	await driveTools.runTools(lane, drive, lane.state.operation.state);

	assert.deepEqual(
		plain(observations),
		[["safe_execute", "persisted", { complete: true }]],
		"the safe/safe replay reruns exactly once with the persisted arguments and memos",
	);
	const safeStart = events.find((event) => event.type === "tool_start" && event.toolCallId === "call-0");
	assert.ok(safeStart, "the replay publishes a recovery tool_start");
	assert.equal(safeStart.recovery, true);
	assert.deepEqual(plain(safeStart.args), { value: "persisted" });
	assert.ok(
		lane.log.indexOf("replay_commit") !== -1 && lane.log.indexOf("replay_commit") < lane.log.indexOf("tool_start"),
		"the replay drops the stale checkpoint before rerunning the effect",
	);
	assert.equal(
		events.some((event) => event.type === "tool_start" && event.toolCallId === "call-1"),
		false,
		"unsafe effects are never replayed",
	);
	const unsafeEnd = events.find((event) => event.type === "tool_end" && event.toolCallId === "call-1");
	assert.equal(unsafeEnd.isError, true);

	const safeEntry = lane.entries.get("result-0");
	assert.deepEqual(plain(safeEntry.message.content), [{ type: "text", text: "safe replay" }]);
	assert.equal(safeEntry.message.isError, false);
	assert.deepEqual(plain(safeEntry.message.usage), safeUsage, "the replayed result keeps its usage");
	assert.deepEqual(plain(safeEntry.message.details), { value: "persisted" });

	const unsafeEntry = lane.entries.get("result-1");
	assert.equal(unsafeEntry.message.isError, true);
	assert.deepEqual(plain(unsafeEntry.message.details), { progress: "kept" }, "the interrupted effect keeps its checkpoint details");
	assert.match(
		unsafeEntry.message.content.at(-1).text,
		/external outcome is unknown/,
		"the interrupted effect is reported as unknown",
	);

	assert.equal(lane.state.operation.state.at, "checkpoint", "the completed batch advances the operation");
	assert.deepEqual(
		lane.state.operation.state.batch === undefined ? [] : lane.state.operation.state.batch.calls.length,
		[],
		"no batch remains open",
	);
}

/* ---------------------------------------------------------------------------------------------------------- *
 * 5. A real after-tool hook clears isError through the drive procedure, and hook admission after a terminal
 *    gate closure reports the closure instead of the pending cancellation.
 * ---------------------------------------------------------------------------------------------------------- */

{
	const hooks = new hooksModule.HookRegistry(() => {});
	const seen = [];
	hooks.on("after_tool", ({ toolName, isError, content }) => {
		seen.push([toolName, isError, plain(content)]);
		return toolName === "failing"
			? { content: [{ type: "text", text: "recovered" }], details: { patched: true }, isError: false }
			: undefined;
	});
	const failingExecute = async () => {
		throw new Error("boom");
	};
	const lane = createLaneFixture({
		hooks,
		tools: [harnessTool("failing", failingExecute), harnessTool("slow", async () => ({ content: [], details: {} }))],
		mode: "sequential",
	});
	const calls = [toolCall(0, "failing", { value: "input" })];
	const operation = operationFor(calls);
	seed(lane, calls, [], operation);
	lane.state.operation.state = operation;

	await driveTools.runTools(lane, drive, lane.state.operation.state);

	assert.deepEqual(seen.length, 1, "the after-tool hook observes the raw executed result");
	assert.equal(seen[0][1], true, "the raw executed result is an error");
	const recovered = lane.entries.get("result-0");
	assert.equal(recovered.message.isError, false, "the hook clears isError on the durable transcript");
	assert.deepEqual(plain(recovered.message.content), [{ type: "text", text: "recovered" }]);
	assert.deepEqual(plain(recovered.message.details), { patched: true });
}

{
	// A tool that is still running when the drive gate is closed with a terminal error.
	const hooks = new hooksModule.HookRegistry(() => {});
	const started = deferred();
	const finish = deferred();
	const gatedDrive = new driveTypes.Drive({ operationId: "operation-closed" }, {});
	const lane = createLaneFixture({
		hooks,
		tools: [
			harnessTool("slow", async () => {
				started.resolve();
				await finish.promise;
